{
  "name": "英特尔 RealSense D435 深度相机",
  "name_en": "Intel RealSense D435 Depth Camera",
  "manufacturer": "Intel",
  "description": "一款面向机器人与机器视觉实验的 RGB-D 深度相机，可采集彩色图像并支持空间感知。该设备常用于目标观察、场景记录、视觉算法测试和实验过程的实时视频采集；从当前证据看，此处主要使用其 RGB 视频输出能力。",
  "description_en": "An RGB-D depth camera for robotics and machine vision experiments, capable of capturing color images and supporting spatial perception. It is commonly used for target observation, scene recording, vision algorithm testing, and live video capture during experiments; based on the available evidence, the RGB video output is the primary function used here.",
  "tag_hints": [
    "Intel RealSense D435",
    "RGB video capture",
    "depth camera",
    "RGB-D imaging",
    "robot vision",
    "machine vision",
    "live video streaming"
  ],
  "actions": [
    {
      "action_name": "auto-setup_ffmpeg_stream",
      "description": "配置并启动相机 RGB 视频流的编码与推流输出。",
      "description_en": "Configure and start encoded streaming output for the camera's RGB video feed."
    },
    {
      "action_name": "auto-camera_response_callback",
      "description": "处理相机返回的响应消息。",
      "description_en": "Handle response messages returned by the camera."
    },
    {
      "action_name": "auto-process_and_queue_image",
      "description": "处理采集到的 RGB 图像并加入视频输出队列。",
      "description_en": "Process captured RGB images and queue them for video output."
    }
  ]
}

